"""Day 4: write §9.12 of docs/ablation_findings.md and docs/day4_justification_table.tex from the Day 4 result JSONs (results/ablation/D4_*.json).
Every table row starts with a unique id cell (`d4.<...>`) so that ablation/verify_day4.py can find the line and re-derive its numbers from the stored dev/test probabilities.
The section sits between <!-- DAY4:BEGIN --> and <!-- DAY4:END --> and is rewritten in place."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
RES = ROOT / "results" / "ablation"
J = lambda n: json.load(open(RES / n))
f4 = lambda v: f"{v:.4f}"
sg = lambda v: f"{v:+.4f}"
ms = lambda v: f"{v[0]:.4f}" + (f" ± {v[1]:.4f}" if v[1] is not None else "")
ci = lambda c: f"[{c[0]:+.4f}, {c[1]:+.4f}]"
SECT = {"informative": "T1", "humanitarian": "T2"}


def build():
    L = []
    w = L.append
    t1, sw, wt, tie1 = J("D4_T1_summary.json"), J("D4_switch_rule_T1.json"), J("D4_T1_weighting_posthoc.json"), J("D4_T1_bilstm_vs_tfidf_dev.json")
    fu1, lat, ts, dep, ov, er = J("D4_T1_fusion.json"), J("D4_t1_latency.json"), J("D4_t1_trainserve.json"), J("D4_t1_deploy_check.json"), J("D4_cross_task_overlap.json"), J("D4_error_analysis.json")
    t2, t2t, pc = J("D4_T2_fusion.json"), J("D4_T2_text_summary.json"), J("D4_t2_param_counts.json")
    w("<!-- DAY4:BEGIN (generated by ablation/d4_make_findings.py; do not edit by hand) -->")
    w("### 9.12 Day 4: model exploration requested by the guide (Task 1 and Task 2)\n")
    w("Protocol and candidate lists: `ablation/SELECTION_RULE_DAY4.md` (committed before the runs; the post-hoc arms are labelled). Splits, seeds 42/43/44 and dev-only selection as in the earlier sections; test is reported afterwards and decides nothing. "
      "Every number below is repeated from `results/ablation/D4_*.json` and re-derived by `ablation/verify_findings.py` (via `ablation/verify_day4.py`) from the stored dev and test probabilities of each run. "
      "Mean ± std are over the 3 seeds; deterministic models (TF-IDF, majority) have one run. No multiplicity correction: the comparisons below are exploratory and use the 'better / worse / not distinguishable' language of §9.2.\n")
    # ---- Task 1
    w("#### 9.12.1 Task 1 (informative vs not informative; text label), sorted by dev weighted F1\n")
    w("| id | Model | seeds | dev wF1 | test acc | test wF1 | test macro-F1 | test bal-acc | test MCC | test ROC-AUC |\n|---|---|---|---|---|---|---|---|---|---|")
    for r in t1:
        w(f"| `d4.t1.{r['model']}` | {r['label']}{' (post-hoc)' if r['posthoc'] else ''} | {r['n_seeds']} | {ms(r['dev_weighted_f1'])} | {ms(r['test_acc'])} | {ms(r['test_weighted_f1'])} | {ms(r['test_macro_f1'])} | {ms(r['test_balanced_acc'])} | {ms(r['test_mcc'])} | {ms(r['test_roc_auc'])} |")
    w("")
    w(f"* `d4.t1.switch` **Pre-registered switch rule (dev).** Dev weighted-F1 gain of BERTweet over TF-IDF + LR ({f4(sw['dev_weighted_f1_tfidf_lr'])}): per seed {', '.join(sg(x) for x in sw['per_seed_point_gain'])}, seed-averaged {sg(sw['seed_avg_gain'])}, "
      f"paired 95% CI {ci(sw['ci95'])} (10,000 resamples); positive at every seed: {sw['positive_at_every_seed']}; decision: {'switch the deployed Task 1 model to BERTweet' if sw['switch'] else 'keep TF-IDF + LR'}.")
    w(f"* `d4.t1.bilstm_tie` BiLSTM + GloVe minus TF-IDF + LR, dev weighted F1: {sg(tie1['point_gain'])} {ci(tie1['ci95'])}: {tie1['verdict']} (post-hoc).")
    tm = wt["trade_off_means"]
    w(f"* `d4.t1.weighting` **Loss weighting for BERTweet (post-hoc; weighting is retained because it was fixed by pre-registration).** Dev balanced-accuracy gain, weighted minus unweighted: {sg(wt['point_gain'])} {ci(wt['ci95'])}. "
      f"Weighting raises not-informative recall at the cost of informative recall (means over 3 seeds, dev / test): not-informative recall {f4(tm['dev']['ni_recall']['weighted'])} / {f4(tm['test']['ni_recall']['weighted'])} vs {f4(tm['dev']['ni_recall']['unweighted'])} / {f4(tm['test']['ni_recall']['unweighted'])}; "
      f"informative recall {f4(tm['dev']['inf_recall']['weighted'])} / {f4(tm['test']['inf_recall']['weighted'])} vs {f4(tm['dev']['inf_recall']['unweighted'])} / {f4(tm['test']['inf_recall']['unweighted'])}; "
      f"not-informative precision {f4(tm['dev']['ni_precision']['weighted'])} / {f4(tm['test']['ni_precision']['weighted'])} vs {f4(tm['dev']['ni_precision']['unweighted'])} / {f4(tm['test']['ni_precision']['unweighted'])}. This is a different operating point, not a safety improvement.\n")
    w("#### 9.12.2 Task 1 fusion (fused minus the best unimodal model of the seed, chosen on dev weighted F1; mean ± std)\n")
    w("| id | Fused model | dev gain wF1 | dev gain macro-F1 | test gain wF1 | test gain macro-F1 |\n|---|---|---|---|---|---|")
    for n, g in fu1["gains"].items():
        w(f"| `d4.t1f.{n}` | {g['label']} | " + " | ".join(f"{sg(g['mean'][sp][k])} ± {g['std'][sp][k]:.4f}" for sp in ("dev", "test") for k in ("weighted_f1", "macro_f1")) + " |")
    w("\nPaired bootstrap (dev decides; test is reporting only; seed-averaged, 10,000 resamples):\n")
    w("| id | Comparison | split | metric | point | 95% CI | verdict |\n|---|---|---|---|---|---|---|")
    for key, c in fu1["bootstrap"].items():
        for sp in ("dev", "test"):
            for k, v in c[sp].items():
                w(f"| `d4.t1b.{key}.{sp}.{k}` | {c['a']} − {c['b']} | {sp} | {k} | {sg(v['point'])} | {ci(v['ci95'])} | {v['verdict']} |")
    w(f"\nAll fusion variants tie on dev (spread of the mean dev weighted F1 across the three fused models: see the table above); none is 'best'. Test split by label agreement (label_text == label_image; agreed n={fu1['subsets']['test']['n_agree']}, "
      f"disagreed n={fu1['subsets']['test']['n_disagree']}); macro-F1 averages the classes present (both, in every subset):\n")
    w("| id | Model | agreed wF1 | agreed macro-F1 | agreed acc | disagreed wF1 | disagreed macro-F1 | disagreed acc |\n|---|---|---|---|---|---|---|---|")
    for n, m in fu1["subsets"]["test"]["models"].items():
        w(f"| `d4.t1s.{n}` | {n} | " + " | ".join(f"{m[g][k]:.4f}" for g in ("agree", "disagree") for k in ("weighted_f1", "macro_f1", "acc")) + " |")
    w("")
    w("#### 9.12.3 Task 1 deployment and latency\n")
    w(f"* `d4.deploy` **Deployed checkpoint = retrain.** Seed 42 was retrained with `--save`: dev weighted F1 {f4(dep['dev_wf1']['deployed'])} (original run {f4(dep['dev_wf1']['original'])}), test weighted F1 {f4(dep['test_wf1']['deployed'])} (original {f4(dep['test_wf1']['original'])}), "
      f"best epoch {dep['best_epoch']['deployed']} (original {dep['best_epoch']['original']}), test-prediction agreement {dep['prediction_agreement']['test']:.4f}; dev temperature {dep['temperature']:.3f}; "
      f"ECE dev {f4(dep['ece_dev']['before'])} to {f4(dep['ece_dev']['after'])}, test {f4(dep['ece_test']['before'])} to {f4(dep['ece_test']['after'])}.")
    s = ts["summary"]
    w(f"* `d4.trainserve` Train/serve check: BERTweet trained on the raw `tweet_text`; the demo passes the raw string. {s['n']} fixed-seed test tweets through the demo code path: argmax matches the stored `bertweet_deploy` predictions on {s['argmax_match_unscaled']} of {s['n']} (unscaled) and {s['argmax_match_calibrated']} of {s['n']} (calibrated); "
      f"largest probability difference {s['max_abs_prob_diff_unscaled']:.4f} (unscaled).\n")
    w("| id | Latency row | what is measured | median ms | p95 ms |\n|---|---|---|---|---|")
    for grp in ("model_call", "end_to_end", "http_round_trip"):
        for n, v in lat[grp].items():
            w(f"| `d4.lat.{grp}.{n}` | {grp} / {n} | {v['what_is_measured']} | {v['median_ms']:.2f} | {v['p95_ms']:.2f} |")
    w("\nThe report's earlier figures ('model call 0.1 to 0.2 s', 'about 1.8 s end to end') have no benchmark script or log in the repository; the 1.8 s matches the HTTP round trip above, the 0.1-0.2 s matches no measurement.\n")
    w("#### 9.12.4 Cross-task overlap (tweet_id): Task 1 rows also present in the Task 2 / Task 3 splits\n")
    w("| id | T1 split | in T2 train | T2 dev | T2 test | T3 train | T3 dev | T3 test |\n|---|---|---|---|---|---|---|---|")
    for sp in ("train", "dev", "test"):
        v = ov["by_tweet_id"][f"T1_{sp}"]
        w(f"| `d4.ov.{sp}` | T1 {sp} | " + " | ".join(str(v[c]) for c in ("T2_train", "T2_dev", "T2_test", "T3_train", "T3_dev", "T3_test")) + " |")
    ix = ov["t3_deployed_index"]
    w(f"\n* `d4.ov.index` T1 test rows in the 2,361-row deployed Task 3 index (tweet_id and image path): {ix['T1_overlap_by_tweet_id']['test']} and {ix['T1_overlap_by_image_path']['test']}. "
      f"Within each task the splits are disjoint for Tasks 1 and 2 (0 shared tweets); the official Task 3 damage splits share {ov['within_task_overlap_tweet_id']['T3']['train&test']} train-test and {ov['within_task_overlap_tweet_id']['T3']['dev&test']} dev-test tweets, "
      "which is why the tweet-disjoint claim applies to the index, not to the official splits.\n")
    # ---- Task 2
    w("#### 9.12.5 Task 2 (8 humanitarian classes; image label): text, image and fusion models\n")
    w("| id | Model | dev macro-F1 | test macro-F1 | test wF1 | test acc | test bal-acc | test MCC | test top-2 | test ROC-AUC |\n|---|---|---|---|---|---|---|---|---|---|")
    for n, r in t2["models"].items():
        w(f"| `d4.t2.{n}` | {r['label']} | {ms(r['dev_macro_f1'])} | {ms(r['test_macro_f1'])} | {ms(r['test_weighted_f1'])} | {ms(r['test_acc'])} | {ms(r['test_balanced_acc'])} | {ms(r['test_mcc'])} | {ms(r['test_top2_acc'])} | {ms(r['test_macro_roc_auc'])} |")
    w("\nClassical text models (selected among the class-weighted ones on dev; the unweighted ComplementNB is a reference row):\n")
    w("| id | Model | dev macro-F1 | test macro-F1 | test wF1 | test acc | test bal-acc | test MCC | test top-2 | test ROC-AUC |\n|---|---|---|---|---|---|---|---|---|---|")
    for n in ("t2_majority", "t2_tfidf_lr", "t2_tfidf_svm", "t2_tfidf_cnb", "t2_tfidf_cnb_bal", "bertweet_text_matched", "bertweet_text_rule8"):
        r = t2t["models"][n]
        w(f"| `d4.t2t.{n}` | {r['label']} | {ms(r['dev_macro_f1'])} | {ms(r['test_macro_f1'])} | {ms(r['test_weighted_f1'])} | {ms(r['test_acc'])} | {ms(r['test_balanced_acc'])} | {ms(r['test_mcc'])} | {ms(r['test_top2_acc'])} | {ms(r['test_macro_roc_auc'])} |")
    a = t2t["arm_selection"]; pb = t2t["bertweet_matched_vs_distilbert_paired"]; vd = t2t["bertweet_vs_distilbert_dev"]
    w(f"\n* `d4.t2t.arm` BERTweet text-only arm selection (rule 13): matched − rule8, dev macro-F1 {sg(a['point'])} {ci(a['ci95'])}: {'tied' if a['tied'] else 'resolved'}; pick: {a['pick']}.")
    w(f"* `d4.t2t.vs_distilbert` BERTweet (matched recipe) vs DistilBERT text-only, per-seed dev macro-F1: BERTweet {', '.join(f4(x) for x in vd['bertweet_matched_per_seed'])}; DistilBERT {', '.join(f4(x) for x in vd['distilbert_per_seed'])}. "
      f"Consistent at every seed on dev, but the paired dev interval marginally includes zero {ci(pb['dev']['macro_f1']['ci95'])} (point {sg(pb['dev']['macro_f1']['point'])}): small, not robust; test macro-F1 {sg(pb['test']['macro_f1']['point'])} {ci(pb['test']['macro_f1']['ci95'])}; "
      f"weighted F1 dev {sg(pb['dev']['weighted_f1']['point'])} {ci(pb['dev']['weighted_f1']['ci95'])}, test {sg(pb['test']['weighted_f1']['point'])} {ci(pb['test']['weighted_f1']['ci95'])} (post-hoc; DistilBERT predictions re-inferred from its checkpoints). "
      "Confound: BERTweet reads the raw tweet text with its own normalisation, DistilBERT the cleaned text.\n")
    w("Pre-registered comparisons and post-hoc comparisons (dev paired bootstrap, seed-averaged, 10,000 resamples; test is reporting only):\n")
    w("| id | Comparison | split | metric | point | 95% CI | verdict |\n|---|---|---|---|---|---|---|")
    for key, c in {**t2["comparisons"], **t2["posthoc"]}.items():
        for sp in ("dev", "test"):
            for k in ("macro_f1", "weighted_f1"):
                v = c[sp][k]
                w(f"| `d4.t2b.{key}.{sp}.{k}` | {c['a']} − {c['b']}{' (post-hoc)' if key in t2['posthoc'] else ''} | {sp} | {k} | {sg(v['point'])} | {ci(v['ci95'])} | {v['verdict']} |")
    w("\nTie-break (SELECTION_RULE_DAY4.md rule 2, 'Ties go to the simplest model.'; 'simplest' = fewest trainable parameters, as in D2 / §9.11; rules 14-19 contain no tie wording of their own):\n")
    w("| id | Comparison | dev macro-F1 tied? | trainable parameters (core / other) | the rule picks | dev weighted F1 (corroboration only) |\n|---|---|---|---|---|---|")
    for key in ("core_vs_L4a", "core_vs_image_only_clip_b32"):
        c = t2["comparisons"][key]; tb = c["tie_break"]
        w(f"| `d4.t2tb.{key}` | {c['a']} − {c['b']} | {'yes' if tb['tied'] else 'no'} | {tb['trainable_core']:,} / {tb['trainable_other']:,} | {tb['pick']} | {sg(c['dev']['weighted_f1']['point'])} {ci(c['dev']['weighted_f1']['ci95'])} ({c['dev']['weighted_f1']['verdict']}) |")
    w("\nFusion gain, whole sets (fused − best single modality of the seed, chosen on dev macro-F1; mean ± std):\n")
    w("| id | Fused model | dev gain macro-F1 | dev gain wF1 | test gain macro-F1 | test gain wF1 |\n|---|---|---|---|---|---|")
    for n, g in t2["gains"].items():
        w(f"| `d4.t2g.{n}` | {n} | " + " | ".join(f"{sg(g['mean'][sp][k])} ± {g['std'][sp][k]:.4f}" for sp in ("dev", "test") for k in ("macro_f1", "weighted_f1")) + " |")
    w("\nFusion gain vs own components (fused − the better, per seed on dev macro-F1, of the two single-modality models it is built from; mean ± std):\n")
    w("| id | Fused model | own components | dev gain macro-F1 | dev gain wF1 | test gain macro-F1 | test gain wF1 |\n|---|---|---|---|---|---|---|")
    for n, g in t2["gains_own"].items():
        w(f"| `d4.t2o.{n}` | {n} | {g['components'][0]} + {g['components'][1]} | " + " | ".join(f"{sg(g['mean'][sp][k])} ± {g['std'][sp][k]:.4f}" for sp in ("dev", "test") for k in ("macro_f1", "weighted_f1")) + " |")
    ag = t2["agreement"]["test"]
    w(f"\nTest set by label agreement (normalised label_text == label_image; agreed n={ag['n_agree']}, disagreed n={ag['n_disagree']}). Macro-F1 averages the classes present in the subset's true labels or predictions (Table VIII's convention); `all8` is the fixed 8-class average. Mean ± std over 3 seeds, descriptive only:\n")
    w("| id | Model | agreed macro-F1 | agreed all8 | agreed wF1 | agreed acc | disagreed macro-F1 | disagreed all8 | disagreed wF1 | disagreed acc |\n|---|---|---|---|---|---|---|---|---|---|")
    for n in t2["subsets"]["agreed"]:
        if n == "n":
            continue
        w(f"| `d4.t2s.{n}` | {n} | " + " | ".join(f"{t2['subsets'][g][n][k]:.3f} ± {t2['subsets'][g][n][k + '_std']:.3f}" for g in ("agreed", "disagreed") for k in ("macro_f1", "macro_f1_all8", "weighted_f1", "acc")) + " |")
    tv = t2["table_viii_check"]
    w(f"\n* `d4.t2s.check` Table VIII check: L4a reproduces the report's subset macro-F1 (agreed {tv['agreed']['here']:.3f}, disagreed {tv['disagreed']['here']:.3f}); the fixed 8-class average gives {tv['agreed']['here_all8']:.3f} for agreed.\n")
    w("#### 9.12.6 Error analysis (rule-based; categories are not human-verified)\n")
    for tag in ("T1", "T2"):
        e = er[tag]; bc = e["by_category"]
        w(f"* `d4.err.{tag}` {e['model']}: {e['n_errors']} errors on {e['n_test']} test rows; text-image mismatch {bc.get('text-image mismatch', 0)}, label ambiguity {bc.get('label ambiguity', 0)}, model error {bc.get('model error', 0)}. The 12 sampled rows are in `docs/day4_error_analysis.md`.")
    w("")
    w("#### 9.12.7 Justification of each architectural choice (choice → alternatives → result on dev → verdict → basis)\n")
    w(JUSTIFICATION(t1, sw, wt, tie1, fu1, t2, t2t, pc))
    w("<!-- DAY4:END -->")
    return "\n".join(L) + "\n"


def jrows(t1, sw, wt, tie1, fu1, t2, t2t, pc):
    """(id, choice, alternatives tried, result on dev, verdict, basis)"""
    d = lambda n: [r for r in t1 if r["model"] == n][0]["dev_weighted_f1"][0]
    bw = fu1["bootstrap"]; c1 = t2["comparisons"]["core_vs_L4a"]["dev"]["macro_f1"]; c2 = t2["comparisons"]["core_vs_image_only_clip_b32"]["dev"]["macro_f1"]
    tm = wt["trade_off_means"]; pbd = t2t["bertweet_matched_vs_distilbert_paired"]["dev"]["macro_f1"]; tm2 = t2t["models"]
    best_fused = bw["best_fused_vs_text_only"]["dev"]["weighted_f1"]
    return [
        ("t1_model", "Task 1 text model: BERTweet (fine-tuned)", "TF-IDF + LR, NB (unweighted / balanced / Complement), Random Forest, Linear SVM, BiLSTM + GloVe, majority class",
         f"dev weighted F1: BERTweet {f4(d('bertweet'))}, BiLSTM {f4(d('bilstm_glove'))}, TF-IDF + LR {f4(d('tfidf_lr'))}, NB (balanced) {f4(d('tfidf_nb_bal'))}, Random Forest {f4(d('tfidf_rf'))}, Linear SVM {f4(d('tfidf_svm'))}, majority {f4(d('majority'))}; "
         f"BERTweet minus TF-IDF + LR {sg(sw['seed_avg_gain'])} {ci(sw['ci95'])}; BiLSTM minus TF-IDF + LR {sg(tie1['point_gain'])} {ci(tie1['ci95'])}",
         "BERTweet better than TF-IDF + LR (CI excludes 0, positive at all 3 seeds); BiLSTM tied with TF-IDF + LR", "pre-registered dev rule (rule 3): resolvable"),
        ("t1_fusion", "Task 1 fusion: none (BERTweet text-only is deployed)", "late fusion (calibrated), early fusion BERTweet + ResNet50 (guide's model), early fusion BERTweet + CLIP L/14",
         f"dev weighted-F1 gain of the best fused model over BERTweet text-only {sg(best_fused['point'])} {ci(best_fused['ci95'])}; guide's core model {sg(bw['guides_core_vs_deployed']['dev']['weighted_f1']['point'])} {ci(bw['guides_core_vs_deployed']['dev']['weighted_f1']['ci95'])}",
         "not distinguishable on dev (all three fused models tie); test intervals exclude 0 narrowly (reporting only); fusion helps only where text and image labels agree",
         "tie-break (simplicity, rule 2): the text-only model has the fewest components"),
        ("t1_loss", "Task 1 loss: inverse-frequency weighted cross-entropy (kept)", "unweighted cross-entropy (post-hoc arm)",
         f"dev balanced-accuracy gain of weighting {sg(wt['point_gain'])} {ci(wt['ci95'])}; not-informative recall {f4(tm['dev']['ni_recall']['weighted'])} vs {f4(tm['dev']['ni_recall']['unweighted'])}, informative recall {f4(tm['dev']['inf_recall']['weighted'])} vs {f4(tm['dev']['inf_recall']['unweighted'])}",
         "weighting changes the operating point (more not-informative predictions), it does not improve weighted F1 or macro-F1 detectably", "kept because it was fixed by pre-registration; not a safety claim"),
        ("t2_text", "Task 2 text encoder (fine-tuned): DistilBERT in the deployed L4a", "BERTweet (matched and rule-8 recipes), TF-IDF + LR / SVM / ComplementNB, frozen MiniLM and MPNet heads (§9.10)",
         f"dev macro-F1: BERTweet matched {f4(tm2['bertweet_text_matched']['dev_macro_f1'][0])}, rule-8 {f4(tm2['bertweet_text_rule8']['dev_macro_f1'][0])}, DistilBERT {f4(t2t['distilbert_text_only']['dev_macro_f1'][0])}, TF-IDF + LR {f4(tm2['t2_tfidf_lr']['dev_macro_f1'][0])}; BERTweet minus DistilBERT {sg(pbd['point'])} {ci(pbd['ci95'])}",
         "BERTweet consistent at every seed on dev but not resolvable (small, not robust); text-only models are far below image models", "tie / not established: the deployed Task 2 model is unchanged (post-hoc comparison; raw vs cleaned input is a confound)"),
        ("t2_image", "Task 2 image backbone: CLIP (L/14 in the ablation-selected model, B/32 in the deployed one)", "DINOv2, CLIP B/32, ResNet-50 (frozen features, image-only head; §9.10 D1)",
         "dev macro-F1: CLIP L/14 0.6124, DINOv2 0.5758, CLIP B/32 0.5679, ResNet-50 0.5418; best minus DINOv2 +0.0366 [+0.0126, +0.0618], minus B/32 +0.0445 [+0.0111, +0.0797], minus ResNet-50 +0.0706 [+0.0372, +0.1084]",
         "CLIP L/14 better than every alternative", "pre-registered Day 2 rule (§9.10, §9.11): resolvable"),
        ("t2_fusion", "Task 2 fusion: the guide's core model (BERTweet + ResNet50) is not adopted; image-only / L4a remain", "late fusion (calibrated), L4a cross-attention, concat, gated-late (§9.10), the core model BERTweet + ResNet50",
         f"core minus L4a, dev macro-F1 {sg(c1['point'])} {ci(c1['ci95'])}; core minus image-only CLIP B/32 head {sg(c2['point'])} {ci(c2['ci95'])}; trainable parameters {pc['core_bertweet_resnet50']:,} (core), {pc['t2_L4a']:,} (L4a), {pc['t2_img_clip_b32_head']:,} (image-only head)",
         "tied on dev macro-F1 (dev weighted F1: worse, corroboration only); test macro-F1 worse for both (reporting only)", "tie-break (rule 2: fewest trainable parameters): L4a over the core model; the image-only head over the core model"),
        ("t2_loss", "Task 2 loss: inverse-frequency weighted cross-entropy (kept)", "9 alternatives (§9.9, Table XIII): unweighted, sqrt-inverse, effective number, focal 1/2, focal 2 + inverse, sampler, logit adjustment, post-hoc",
         "dev macro-F1 on L/14: focal loss (gamma 1) 0.6321, unweighted 0.6237, inverse-frequency 0.6124; on B/32: focal loss (gamma 2) 0.6016, inverse-frequency 0.5679; best minus inverse-frequency +0.0197 [-0.0122, +0.0480] (L/14), +0.0337 [-0.0019, +0.0651] (B/32)",
         "7 of 10 arms tied with the best on both backbones; the two backbones pick different arms", "no new loss adopted (rule 5 of the imbalance selection rule); inverse-frequency is 'not shown worse', not 'as good'"),
        ("t3_probe", "Task 3: logistic probe predicts, 5-NN supplies the evidence", "v2's 5-NN majority vote (k = 5), image-only and text-only retrieval (§9.2, §9.3)",
         "test macro-F1 0.6146 (hybrid probe) vs 0.4914 (5-NN); bootstrap +0.1231, 95% interval +0.0615 to +0.1861 (test-sampling interval of §9.2; the probe's C was chosen on dev)",
         "probe better than 5-NN", "paired bootstrap on test (reporting, §9.2); not a dev-selected decision"),
    ]


def JUSTIFICATION(t1, sw, wt, tie1, fu1, t2, t2t, pc):
    rows = jrows(t1, sw, wt, tie1, fu1, t2, t2t, pc)
    out = ["| id | Choice | Alternatives tried | Result (dev unless stated) | Verdict | Basis |\n|---|---|---|---|---|---|"]
    for i, c, a, r, v, b in rows:
        out.append(f"| `d4.j.{i}` | {c} | {a} | {r} | {v} | {b} |")
    out.append("\n`d4.j.limits` **Limitations.** (1) Three seeds per model and no multiplicity correction: about 15-20 new comparisons, all exploratory. (2) The deployed Task 1 checkpoint is a retrain of seed 42 (dev weighted F1 0.8289 against 0.8321 originally; 94.3% test-prediction agreement); same-seed run-to-run variation (0.0032) exceeds the inter-seed dev spread (0.0030), so seed selection is within noise. "
               "(3) The Task 1 and Task 2 splits overlap by tweet (1,603 of the 2,237 Task 1 test rows are in the Task 2 train split), so no Task 1 model may use anything trained on Task 2; this is asserted in the code. (4) The error-analysis categories are assigned by rule, not by human inspection.\n")
    return "\n".join(out)


def tex_table():
    t1, sw, wt, tie1 = J("D4_T1_summary.json"), J("D4_switch_rule_T1.json"), J("D4_T1_weighting_posthoc.json"), J("D4_T1_bilstm_vs_tfidf_dev.json")
    fu1, t2, t2t, pc = J("D4_T1_fusion.json"), J("D4_T2_fusion.json"), J("D4_T2_text_summary.json"), J("D4_t2_param_counts.json")
    esc = lambda s: s.replace("&", r"\&").replace("%", r"\%").replace("_", r"\_").replace("#", r"\#").replace("±", r"$\pm$").replace("−", "-").replace("→", r"$\rightarrow$")
    rows = jrows(t1, sw, wt, tie1, fu1, t2, t2t, pc)
    body = "".join(f"{esc(c)} & {esc(a)} & {esc(r)} & {esc(v)} & {esc(b)} \\\\\n\\midrule\n" for _, c, a, r, v, b in rows)
    return ("% LaTeX draft, generated by ablation/d4_make_findings.py from the same rows as docs/ablation_findings.md section 9.12.7 (requires booktabs, tabularx or longtable as the template allows)\n"
            "\\begin{table*}[t]\n\\centering\n\\scriptsize\n\\caption{Justification of each architectural choice: the choice, the alternatives tried, the result on the development split, the verdict, and the basis (a resolvable difference or the pre-registered tie-break). Exploratory comparisons; no multiplicity correction.}\n"
            "\\label{tab:justification}\n\\begin{tabular}{p{2.6cm}p{3.0cm}p{5.4cm}p{3.2cm}p{2.8cm}}\n\\toprule\nChoice & Alternatives tried & Result & Verdict & Basis \\\\\n\\midrule\n" + body + "\\bottomrule\n\\end{tabular}\n\\end{table*}\n")


if __name__ == "__main__":
    doc_path = ROOT / "docs" / "ablation_findings.md"
    doc = doc_path.read_text(encoding="utf8")
    new = build()
    if "<!-- DAY4:BEGIN" in doc:
        a, b = doc.index("<!-- DAY4:BEGIN"), doc.index("<!-- DAY4:END -->") + len("<!-- DAY4:END -->\n")
        doc = doc[:a] + new + doc[b:]
    else:
        doc = doc.rstrip("\n") + "\n\n" + new
    doc_path.write_text(doc, encoding="utf8")
    (ROOT / "docs" / "day4_justification_table.tex").write_text(tex_table(), encoding="utf-8")
    print(f"wrote section 9.12 ({new.count(chr(10))} lines) and docs/day4_justification_table.tex")
